def inbb(b,c,pad=15):
    if not b['bb']: return None
    x,y,w,h=b['bb'];X,Y=c[0],-c[1]
    return x-pad<=X<=x+w+pad and y-pad<=Y<=y+h+pad
out=[]
for n,bid in MAP.items():
    if not bid or bid not in B: continue
    b=B[bid];ps=[p for p in P if p.get('i')==n]
    imp=[(c[1],c[2],c[4]) for p in ps for c in p.get('ch',[]) if (c[0] or '').startswith('cronologia di impianto')]
    ab=[(c[1],c[2]) for p in ps for c in p.get('ch',[]) if (c[0] or '').startswith('cronologia di abbandono')]
    a0=[p['a0'] for p in ps if p.get('a0') is not None]
    ins=[inbb(b,p['_c']) for p in ps]
    d=min(math.dist(p['_c'],b['c']) for p in ps) if b['c'] and None not in b['c'] else -1
    out.append((n,bid,b['from'],b['to'],b['date'][:60],len(ps),min(a0) if a0 else None,sorted(set(imp),key=str)[:4],sorted(set(ab),key=str)[:3],sum(1 for x in ins if x),len(ins),round(d)))
for o in out: print(o)
